#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ТІЛЬКИ ЧИТАННЯ. Підсумок: усі угоди зі статтею ЛВЗК у доходних рахунках, за статусом."""
import collections, os, sys, urllib.parse
BASE = "/root/unitex-finrep"
sys.path.insert(0, os.path.join(BASE, "engine"))
os.chdir(BASE)
from odata_client import ODataClient
c = ODataClient()

def page(ent, sel):
    out, skip = [], 0
    while True:
        p = "/%s?$format=json&$top=1000&$skip=%d&$select=%s" % (ent, skip, ",".join(sel))
        b = c._get(urllib.parse.quote(p, safe="/?&=$,'"))["value"]
        out += b
        if len(b) < 1000:
            return out
        skip += 1000

def f(x):
    try: return float(x or 0)
    except (TypeError, ValueError): return 0.0

def d10(x):
    x = str(x or "")
    return "" if (not x or x.startswith("0001-01-01")) else x[:10]

def dmy(x):
    return "%s.%s.%s" % (x[8:10], x[5:7], x[2:4]) if x else "—"

def names(ent):
    return {r["Ref_Key"]: (r.get("Description") or "").strip()
            for r in page(ent, ["Ref_Key", "Description"])}

art = names("Catalog_СтатьиСчета"); acc = names("Catalog_ВидОплаты")
cli = names("Catalog_Клиенты"); cur = names("Catalog_Валюты")
LOC = {k for k, v in art.items() if v == "Локальні витрати за кордоном"}
UK = {"Завершена": "Завершена", "ВыставленСчет": "Виставлений рахунок",
      "Выполняется": "Виконується", "Букинг": "Букінг", "Отменена": "Скасована"}

deal = {}
for r in page("Document_Сделка", ["Ref_Key", "Number", "Статус", "обработана",
                                  "DeletionMark", "Клиент_Key", "ДатаЗавершения"]):
    deal[r["Ref_Key"]] = {"num": (r.get("Number") or "").lstrip("0"),
                          "st": UK.get(str(r.get("Статус") or ""), str(r.get("Статус") or "")),
                          "pr": bool(r.get("обработана")), "del": bool(r.get("DeletionMark")),
                          "cli": cli.get(r.get("Клиент_Key"), ""),
                          "done": d10(r.get("ДатаЗавершения"))}

inv = {r["Ref_Key"]: r for r in page("Document_Счет",
       ["Ref_Key", "Number", "Date", "Сделка_Key", "СтатусСчета", "Posted",
        "Информативный", "видОплаты_Key", "Валюта_Key"])}

hit = collections.defaultdict(float)
for r in page("Document_Счет_ТЧ", ["Ref_Key", "Статья_Key", "Сумма_УЕ"]):
    if r.get("Статья_Key") in LOC and r.get("Ref_Key") in inv:
        hit[r["Ref_Key"]] += f(r.get("Сумма_УЕ"))

grp = collections.defaultdict(lambda: {"inv": 0, "deals": set(), "sum": 0.0, "rows": []})
for rk, s in hit.items():
    r = inv[rk]; d = deal[r["Сделка_Key"]]
    if not r.get("Posted"):
        g = "0. рахунок не проведений"
    elif r.get("Информативный"):
        g = "0. рахунок інформативний"
    elif d["st"] == "Завершена" and d["pr"]:
        g = "1. ЗАКРИТІ (Завершена + галочка) — у відборі"
    else:
        g = "2. %s%s" % (d["st"], "" if d["pr"] else " (без галочки)")
    x = grp[g]
    x["inv"] += 1; x["deals"].add(d["num"]); x["sum"] += s
    x["rows"].append((d["num"], d["cli"], (r.get("Number") or "").lstrip("0"),
                      dmy(d10(r.get("Date"))), s,
                      acc.get(r.get("видОплаты_Key"), ""), cur.get(r.get("Валюта_Key"), ""),
                      d["done"]))

tot_i = tot_s = 0
for g in sorted(grp):
    x = grp[g]
    tot_i += x["inv"]; tot_s += x["sum"]
    print("\n### %s — %d рахунків, %d угод, %.2f УО" % (g, x["inv"], len(x["deals"]), x["sum"]))
    for num, c2, inum, dt, s, a, v, done in sorted(x["rows"], key=lambda t: int(t[0] or 0)):
        print("   угода %-5s %-22s рах.%-5s від %s  %8.2f УО  %-24s %s%s"
              % (num, c2[:22] or "(порожньо)", inum, dt, s, a, v,
                 "  заверш. " + dmy(done) if done else ""))
print("\n=== РАЗОМ: %d рахунків, %.2f УО ===" % (tot_i, tot_s))
PYEOF
python3 /root/lc_sum.py > /root/lc_sum.txt 2>&1; wc -l /root/lc_sum.txt; sed -n '1,20p' /root/lc_sum.txt
